package br.com.admeclesial.application.catequese;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import org.springframework.beans.factory.annotation.Autowired;
import br.com.admeclesial.domain.catequese.*; import br.com.admeclesial.infrastructure.persistence.catequese.*; import br.com.admeclesial.infrastructure.persistence.pessoa.PessoaRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.util.StringUtils; import java.util.*;
@Service public class InscricaoCatequeseApplicationService {
 @Autowired private SegurancaOrganizacaoService seguranca;
 private final InscricaoCatequeseRepository repository; private final TurmaCatequeseRepository turmaRepository; private final PessoaRepository pessoaRepository;
 public InscricaoCatequeseApplicationService(InscricaoCatequeseRepository r,TurmaCatequeseRepository t,PessoaRepository p){repository=r;turmaRepository=t;pessoaRepository=p;}
 @Transactional public InscricaoCatequeseResponse criar(InscricaoCatequeseRequest r){var turma=turmaRepository.findByUuid(r.turmaCatequeseUuid()).orElseThrow(()->new CatequeseBusinessException("Turma de catequese não encontrada."));validarAcesso(turma.getOrganizacaoEclesial().getUuid());var pessoa=pessoaRepository.findByUuid(r.pessoaUuid()).orElseThrow(()->new CatequeseBusinessException("Pessoa não encontrada."));if(!pessoa.isAtivo())throw new CatequeseBusinessException("Não é possível inscrever uma pessoa inativa.");if(turma.getStatus()!=StatusCatequese.PLANEJADA&&turma.getStatus()!=StatusCatequese.ATIVA)throw new CatequeseBusinessException("Não é possível realizar inscrição em turma encerrada ou cancelada.");if(repository.existsInscricaoAtivaNaEtapa(pessoa.getId(),turma.getEtapaCatequese().getCatequese().getId(),turma.getEtapaCatequese().getId(),StatusInscricaoCatequese.ATIVA))throw new CatequeseBusinessException("A pessoa já possui inscrição ativa nesta etapa da catequese.");var e=new InscricaoCatequese();e.setTurmaCatequese(turma);e.setPessoa(pessoa);e.setDataInscricao(r.dataInscricao()==null?java.time.LocalDate.now():r.dataInscricao());e.setStatus(r.status()==null?StatusInscricaoCatequese.ATIVA:r.status());e.setObservacao(text(r.observacao()));return toResponse(repository.save(e));}
 @Transactional(readOnly=true) public InscricaoCatequeseResponse buscar(UUID uuid){var e=repository.findByUuid(uuid).orElseThrow(()->new CatequeseBusinessException("Inscrição de catequese não encontrada."));validarAcesso(e.getTurmaCatequese().getOrganizacaoEclesial().getUuid());return toResponse(e);}
 @Transactional(readOnly=true) public List<InscricaoCatequeseResponse> listarPorTurma(UUID uuid){var t=turmaRepository.findByUuid(uuid).orElseThrow(()->new CatequeseBusinessException("Turma de catequese não encontrada."));validarAcesso(t.getOrganizacaoEclesial().getUuid());return repository.findAllByTurmaCatequeseIdOrderByDataInscricaoAsc(t.getId()).stream().map(this::toResponse).toList();}
 private InscricaoCatequeseResponse toResponse(InscricaoCatequese e){return new InscricaoCatequeseResponse(e.getUuid(),e.getTurmaCatequese().getUuid(),e.getPessoa().getUuid(),e.getPessoa().getNome(),e.getDataInscricao(),e.getStatus(),e.getObservacao());}
 private String text(String v){return StringUtils.hasText(v)?v.trim():null;}

 private void validarAcesso(java.util.UUID uuid){if(seguranca!=null)seguranca.validarAcesso(uuid);}
}
